const manifest = {"deploy":"assets/icons/actions/deploy.svg","architecture":"assets/icons/architecture/architecture.svg","pull-request":"assets/icons/actions/pull-request.svg","pipeline":"assets/icons/actions/pipeline.svg","build":"assets/icons/actions/build.svg","tests":"assets/icons/actions/tests.svg","security":"assets/icons/actions/security.svg","analysis":"assets/icons/architecture/analysis.svg","diff":"assets/icons/architecture/diff.svg","circular":"assets/icons/architecture/circular.svg","orphans":"assets/icons/architecture/orphans.svg","source":"assets/icons/architecture/source.svg","success":"assets/icons/status/success.svg","failure":"assets/icons/status/failure.svg","warning":"assets/icons/status/warning.svg","info":"assets/icons/status/info.svg","duration":"assets/icons/actions/duration.svg","artifacts":"assets/icons/actions/artifacts.svg","preview":"assets/icons/actions/preview.svg","ploocky":"assets/icons/actions/ploocky.svg","orb":"assets/icons/projects/orb.svg","rodverse":"assets/icons/projects/rodverse.svg","userscripts":"assets/icons/projects/userscripts.svg","shell":"assets/icons/projects/shell.svg","photointel":"assets/icons/projects/photointel.svg","jardim":"assets/icons/projects/jardim.svg","ast-explorer":"assets/icons/projects/ast-explorer.svg","ejc":"assets/icons/projects/ejc.svg","rod-actions":"assets/icons/projects/rod-actions.svg"};
export const DEFAULT_BASE_URL = 'https://raw.githubusercontent.com/rodkisten/github/main/packages/comment-kit';
export function bannerMarkdown(key, baseUrl = DEFAULT_BASE_URL) { if (!['preview','architecture','security','diff','failure','ploocky','build','tests'].includes(key)) throw Error('Unknown banner'); return '![Rod Actions · '+key+']('+url(baseUrl).replace(/\/$/,'')+'/assets/banners/'+key+'.png)'; }
const esc=s=>String(s).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('|','&#124;').replaceAll('\n',' ');
const url=s=>{const u=new URL(s);if(u.protocol!=='https:')throw Error('HTTPS required');return u.href.replaceAll('(','%28').replaceAll(')','%29');};
export class Comment {
 constructor({baseUrl=DEFAULT_BASE_URL,marker='rod-comment-kit'}={}){this.base=url(baseUrl).replace(/\/$/,'');if(!/^[\w-]+$/.test(marker))throw Error('Invalid marker');this.parts=[`<!-- ${marker} -->`];}
 asset(path){return `${this.base}/${path}`;}
 icon(key){if(!manifest[key])throw Error('Unknown icon '+key);return `<img src="${this.asset(manifest[key].replace('.svg','.png'))}" width="20" height="20" alt="${esc(key)}">`;}
 banner(key){if(!['preview','architecture','security','diff','failure','ploocky','build','tests'].includes(key))throw Error('Unknown banner');this.parts.push(bannerMarkdown(key,this.base));return this;}
 info(text){this.parts.push('> [!NOTE]\n> **INFO:** '+esc(text));return this;}
 metrics(rows){this.parts.push(['| Metric | Base | HEAD | Δ |','| --- | ---: | ---: | ---: |',...rows.map(r=>`| ${esc(r.name)} | ${esc(r.base)} | ${esc(r.head)} | ${esc(r.delta)} |`)].join('\n'));return this;}
 details(title,body){this.parts.push(`<details>\n<summary>${esc(title)}</summary>\n\n${body}\n\n</details>`);return this;}
 mermaid(graph,{collapsed=true}={}){if(graph.includes('```'))throw Error('Invalid Mermaid fence');const body='```mermaid\n'+graph+'\n```';return collapsed?this.details('Dependency graph',body):(this.parts.push(body),this);}
 link(label,href){this.parts.push(`[${esc(label).replaceAll('[','&#91;').replaceAll(']','&#93;')}](${url(href)})`);return this;}
 footer(){this.parts.push('<sub>Rod Actions · Comment Kit</sub>');return this;}
 render(){const body=this.parts.join('\n\n');if(body.length>65000)throw Error('GitHub body limit');return body;}
}
